async function retrieveSystemKnowledgeByType(graphType, type, params, userId) {
  if (graphType === "photograph") {
    if (type === "portrait") return retrieveSystemKnowledgeForPortrait(params, userId);
    if (type === "landscape") return retrieveSystemKnowledgeForLandscape(params, userId);
    if (type === "cinematic") return retrieveSystemKnowledgeForCinematic(params, userId);
    if (type === "commercial") return retrieveSystemKnowledgeForCommercial(params, userId);
    if (type === "documentary") return retrieveSystemKnowledgeForDocumentary(params, userId);
  }
  if (graphType === "design") {
    if (type === "3d") return retrieveSystemKnowledgeFor3d(params, userId);
    if (type === "manual") return retrieveSystemKnowledgeForManual(params, userId);
    if (type === "poster") return retrieveSystemKnowledgeForPoster(params, userId);
    if (type === "icon") return retrieveSystemKnowledgeForIcon(params, userId);
  }
  if (graphType === "painting") {
    if (type === "illustration") return retrieveSystemKnowledgeForIllustration(params, userId);
    if (type === "comic") return retrieveSystemKnowledgeForComic(params, userId);
    if (type === "conceptArt") return retrieveSystemKnowledgeForConceptArt(params, userId);
    if (type === "cartoon") return retrieveSystemKnowledgeForCartoon(params, userId);
  }
  return null;
}
